5628	### Classification priority
5629	
5630	```rust
5631	pub(crate) fn classify(file: &Utf8Path, source: &str, loc: usize, tree: &SourceFile) -> InspectEntry {
5632	    let mut traits: Vec<ast::Trait> = Vec::new();
5633	    let mut structs: Vec<ast::Struct> = Vec::new();
5634	    let mut enums: Vec<ast::Enum> = Vec::new();
5635	    let mut impls: Vec<ast::Impl> = Vec::new();
5636	    let mut uses: Vec<ast::Use> = Vec::new();
5637	    let mut modules: Vec<ast::Module> = Vec::new();
5638	
5639	    for item in tree.items() {
5640	        match item {
5641	            ast::Item::Trait(t) => traits.push(t),
5642	            ast::Item::Struct(s) => structs.push(s),
5643	            ast::Item::Enum(e) => enums.push(e),
5644	            ast::Item::Impl(i) => impls.push(i),
5645	            ast::Item::Use(u) => uses.push(u),
5646	            ast::Item::Module(m) => modules.push(m),
5647	            _ => {}
5648	        }
5649	    }
5650	
5651	    let deps = classify_uses(&uses, source);
5652	
5653	    // Priority 1: traits.
5654	    if let Some(t) = traits.into_iter().next() {
5655	        return InspectEntry::RustTrait(build_trait_entry(file, &t, deps, loc));
5656	    }
5657	
5658	    // Priority 2: structs — pick the one with the most methods, then by field count.
5659	    let methods_by_owner = collect_impl_methods(&impls);
5660	    let trait_impls_by_owner = collect_trait_impls(&impls);
5661	    if let Some(s) = pick_main_struct(structs, &methods_by_owner) {
5662	        return InspectEntry::RustStruct(build_struct_entry(file, &s, tree, &methods_by_owner,
5663	            &trait_impls_by_owner, deps, loc));
5664	    }
5665	
5666	    // Priority 3: enums.
5667	    if let Some(e) = enums.into_iter().next() {
5668	        return InspectEntry::RustEnum(build_enum_entry(file, &e, deps, loc));
5669	    }
5670	
5671	    // Priority 4: module / re-export fallback.
5672	    let mut re_exports = Vec::new();
5673	    for u in &uses {
5674	        if let Some(text) = pub_use_text(u) {
5675	            re_exports.push(text);
5676	        }
5677	    }
5678	    for m in &modules {
5679	        if let Some(text) = pub_mod_text(m) {
5680	            re_exports.push(text);
5681	        }
5682	    }
5683	
5684	    InspectEntry::RustModule(RustModuleEntry {
5685	        file: file.to_owned(),
5686	        re_exports,
5687	        deps,
5688	        loc,
5689	    })
5690	}
5691	```
5692	
5693	Traits > most-prominent struct > first enum > module fallback — matching the regex stub's priority. Multi-struct files surface the struct with the most methods (`method_count * 100 + field_count` score).
