6224	### Change collection
6225	
6226	```rust
6227	fn collect_changes(root: &Utf8Path, base: &str, head: &str, include_line_ranges: bool) -> Result<CollectedChanges> {
6228	    let repo = open_repo(root)?;
6229	    let from = resolve_tree(&repo, base)?;
6230	    let to = resolve_tree(&repo, head)?;
6231	    let mut changes: Vec<GitChangedFile> = Vec::new();
6232	    let mut line_ranges: BTreeMap<Utf8PathBuf, Vec<LineRange>> = BTreeMap::new();
6233	    let mut changed_line_count = 0usize;
6234	    let mut changed_hunk_count = 0usize;
6235	
6236	    let mut change_platform = from.changes().map_err(|err| MonoklError::Git { /* … */ })?;
6237	    let mut diff_cache = if include_line_ranges {
6238	        Some(repo.diff_resource_cache_for_tree_diff().map_err(/* … */)?)
6239	    } else { None };
6240	    change_platform.options(|opts| {
6241	        opts.track_rewrites(Some(gix::diff::Rewrites::default())).track_path();
6242	    });
6243	    change_platform.for_each_to_obtain_tree(&to, |change| {
6244	        let Some(path) = relative_path_from_change(&change) else {
6245	            return Ok::<ControlFlow<()>, MonoklError>(ControlFlow::Continue(()));
6246	        };
6247	
6248	        let kind = match change {
6249	            gix::object::tree::diff::Change::Addition { .. } => GitFileChangeKind::Added,
6250	            gix::object::tree::diff::Change::Deletion { .. } => GitFileChangeKind::Deleted,
6251	            gix::object::tree::diff::Change::Modification { .. } => GitFileChangeKind::Modified,
6252	            gix::object::tree::diff::Change::Rewrite { copy, .. } => {
6253	                if copy {
6254	                    GitFileChangeKind::Added
6255	                } else {
6256	                    match relative_source_path(&change) {
6257	                        Some(from) => GitFileChangeKind::Renamed { from },
6258	                        None => GitFileChangeKind::Modified,
6259	                    }
6260	                }
6261	            }
6262	        };
6263	
6264	        if include_line_ranges {
6265	            let ranges = if let Some(diff_cache) = diff_cache.as_mut() {
6266	                line_ranges_for_change(&change, diff_cache)?
6267	            } else { Vec::new() };
6268	            if !ranges.is_empty() {
6269	                changed_hunk_count += ranges.len();
6270	                changed_line_count += ranges.iter()
6271	                    .map(|range| range.end.saturating_sub(range.start) + 1).sum::<usize>();
6272	                line_ranges.insert(path.clone(), ranges);
6273	            }
6274	        }
6275	
6276	        changes.push(GitChangedFile { path, kind });
6277	        Ok(ControlFlow::Continue(()))
6278	    }).map_err(/* … */)?;
6279	    Ok(CollectedChanges { files: changes, line_ranges, changed_line_count, changed_hunk_count })
6280	}
6281	```
6282	
6283	`line_ranges_for_change` uses `gix::diff::blob::diff` with the platform's `InternalDiff` operation, harvesting `after: Range<u32>` head-side ranges and converting them to 1-based inclusive `LineRange { start, end }`. Binary and external-diff cases yield empty ranges.
