6360	    let blob = object.try_into_blob()
6361	        .map_err(|_| format!("{git_ref}:{path}: object is not a blob"))?;
6362	    std::str::from_utf8(blob.data.as_ref())
6363	        .map(ToOwned::to_owned)
6364	        .map_err(|err| format!("{git_ref}:{path}: non-UTF-8 blob: {err}"))
6365	}
