6657	                    "{} is not supported for {} files (requires {} precision, analyzer exposes {})",
6658	                    requirement.operation,
6659	                    language_label(analyzer.language_id()),
6660	                    precision_label(requirement.minimum),
6661	                    precision_label(precision)
6662	                ),
6663	            });
6664	        }
6665	        return false;
