6705	    let ca = a.canonicalize_utf8().ok();
6706	    let cb = b.canonicalize_utf8().ok();
6707	    match (ca, cb) {
6708	        (Some(ca), Some(cb)) => ca == cb,
6709	        _ => false,
6710	    }
