6754	pub(crate) fn precision_label(precision: CapabilityPrecision) -> &'static str {
6755	    match precision {
6756	        CapabilityPrecision::Unsupported => "unsupported",
6757	        CapabilityPrecision::Heuristic => "heuristic",
6758	        CapabilityPrecision::Structural => "structural",
6759	        CapabilityPrecision::Exact => "exact",
6760	    }
6761	}
