6870	pub fn candidate_language(path: &Utf8Path) -> Option<LanguageId> {
6871	    match path.extension().unwrap_or("").to_ascii_lowercase().as_str() {
6872	        "ts" | "tsx" | "js" | "jsx" | "mjs" | "cjs" | "mts" | "cts" => Some(LanguageId::TypeScript),
6873	        "rs" => Some(LanguageId::Rust),
