778	pub fn parse(input: &str) -> Result<Vec<ParsedTerm>> {
779	    const LIMIT: usize = 64;
780	    if input.trim().is_empty() {
781	        return Ok(Vec::new());
782	    }
783	    let mut lexer = Lexer::new(input);
784	    let mut terms: Vec<ParsedTerm> = Vec::new();
785	    loop {
786	        let tok = lexer.next_token();
787	        match tok {
788	            Token::Eof => break,
789	            Token::Plus => {
790	                let content = lexer.next_token();
791	                if let Some(term) = content_to_term(content, Modifier::Required) {
792	                    terms.push(term);
793	                }
794	            }
795	            Token::Minus => {
796	                let content = lexer.next_token();
797	                if let Some(term) = content_to_term(content, Modifier::Excluded) {
798	                    terms.push(term);
799	                }
800	            }
801	            Token::RegexPrefix => {
802	                let pattern_tok = lexer.next_token();
803	                match pattern_tok {
804	                    Token::Word(raw) | Token::QuotedString(raw) => {
805	                        terms.push(ParsedTerm {
806	                            modifier: Modifier::Optional,
807	                            pattern: raw,
808	                            is_regex: true,
809	                        });
810	                    }
811	                    _ => {}
812	                }
813	            }
814	            Token::Word(w) => {
815	                terms.push(ParsedTerm {
