// Compile probe for SPEC-010's AC-009 rewrite: verify the innermost_walk_error()
// recursive unwrap + exhaustive leaf match actually compiles against the real
// `ignore` crate, with no wildcard arm.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ErrorCode {
    InvalidInput,
    NotFound,
    Forbidden,
    ExternalFailure,
}

fn innermost_walk_error(e: &ignore::Error) -> &ignore::Error {
    match e {
        ignore::Error::WithLineNumber { err, .. } => innermost_walk_error(err),
        ignore::Error::WithPath { err, .. } => innermost_walk_error(err),
        ignore::Error::WithDepth { err, .. } => innermost_walk_error(err),
        ignore::Error::Partial(errs) if errs.len() == 1 => innermost_walk_error(&errs[0]),
        other => other,
    }
}

fn io_kind_to_code(kind: std::io::ErrorKind) -> ErrorCode {
    match kind {
        std::io::ErrorKind::NotFound => ErrorCode::NotFound,
        std::io::ErrorKind::PermissionDenied => ErrorCode::Forbidden,
        _ => ErrorCode::ExternalFailure,
    }
}

// Attempt 1: try to write a fully exhaustive match with all 9 top-level variants,
// including WithLineNumber/WithPath/WithDepth as unreachable-after-unwrap arms,
// and Partial as a single unguarded arm branching internally. NO wildcard arm.
fn classify(e: &ignore::Error) -> ErrorCode {
    let leaf = innermost_walk_error(e);
    match leaf {
        ignore::Error::Io(io_err) => io_kind_to_code(io_err.kind()),
        ignore::Error::Glob { .. } => ErrorCode::InvalidInput,
        ignore::Error::Loop { .. } => ErrorCode::ExternalFailure,
        ignore::Error::UnrecognizedFileType(_) => ErrorCode::InvalidInput,
        ignore::Error::InvalidDefinition => ErrorCode::InvalidInput,
        ignore::Error::Partial(errs) => {
            // innermost_walk_error already reduced len==1 away; this arm only
            // ever sees len != 1 (0 or 2+) in practice, but must still be
            // exhaustive over Vec<Error> generically -- no guard needed since
            // we handle the value unconditionally inside the arm body.
            let _ = errs;
            ErrorCode::ExternalFailure
        }
        // These three are unreachable after innermost_walk_error's recursion,
        // but the match must name them explicitly since there's no wildcard.
        ignore::Error::WithLineNumber { .. } => unreachable!("innermost_walk_error unwraps this"),
        ignore::Error::WithPath { .. } => unreachable!("innermost_walk_error unwraps this"),
        ignore::Error::WithDepth { .. } => unreachable!("innermost_walk_error unwraps this"),
    }
}

fn main() {
    // Exercise a few real constructions to prove the enum shapes match what
    // the spec assumes, and that classify() actually runs without panicking
    // on realistic inputs.
    let io_err = ignore::Error::Io(std::io::Error::new(std::io::ErrorKind::NotFound, "x"));
    println!("{:?}", classify(&io_err));

    let glob_err = ignore::Error::Glob { glob: Some("**[".to_string()), err: "bad glob".to_string() };
    println!("{:?}", classify(&glob_err));

    let nested = ignore::Error::WithPath {
        path: std::path::PathBuf::from(".gitignore"),
        err: Box::new(ignore::Error::WithLineNumber {
            line: 3,
            err: Box::new(ignore::Error::Glob { glob: Some("**[".to_string()), err: "bad glob".to_string() }),
        }),
    };
    println!("{:?}", classify(&nested));

    let loop_err = ignore::Error::Loop {
        ancestor: std::path::PathBuf::from("/a"),
        child: std::path::PathBuf::from("/a/b"),
    };
    println!("{:?}", classify(&loop_err));

    let unrecog = ignore::Error::UnrecognizedFileType("wat".to_string());
    println!("{:?}", classify(&unrecog));

    let invdef = ignore::Error::InvalidDefinition;
    println!("{:?}", classify(&invdef));

    let partial_multi = ignore::Error::Partial(vec![
        ignore::Error::InvalidDefinition,
        ignore::Error::InvalidDefinition,
    ]);
    println!("{:?}", classify(&partial_multi));

    let partial_empty = ignore::Error::Partial(vec![]);
    println!("{:?}", classify(&partial_empty));

    let partial_single = ignore::Error::Partial(vec![ignore::Error::Loop {
        ancestor: std::path::PathBuf::from("/a"),
        child: std::path::PathBuf::from("/a/b"),
    }]);
    println!("{:?}", classify(&partial_single));

    // Confirm ignore::Error never overrides source() -- this is the premise
    // the whole rewrite depends on.
    use std::error::Error as StdError;
    let e: &dyn StdError = &io_err;
    println!("source() is none: {}", e.source().is_none());
}

